 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Support Contact Form</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0b1120;
         --bg-accent: #111827;
         --panel: rgba(15, 23, 42, 0.92);
         --panel-border: rgba(148, 163, 184, 0.18);
         --text: #e5eefc;
         --muted: #a5b4cf;
         --primary: #7dd3fc;
         --primary-strong: #38bdf8;
         --danger: #fca5a5;
         --danger-strong: #ef4444;
         --success: #86efac;
         --shadow: 0 24px 60px rgba(2, 6, 23, 0.55);
         --radius: 20px;
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
         background:
           radial-gradient(circle at top, rgba(56, 189, 248, 0.18), transparent 32%),
           linear-gradient(180deg, #020617 0%, var(--bg) 48%, #111827 100%);
         color: var(--text);
       }

       a,
       button,
       input {
         font: inherit;
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         transform: translateY(-180%);
         padding: 0.75rem 1rem;
         border-radius: 0.75rem;
         background: #ffffff;
         color: #020617;
         font-weight: 700;
         text-decoration: none;
         z-index: 10;
       }

       .skip-link:focus-visible {
         transform: translateY(0);
       }

       main {
         width: min(100%, 72rem);
         margin: 0 auto;
         padding: 3rem 1rem 4rem;
       }

       .page-shell {
         display: grid;
         gap: 1.5rem;
         align-items: start;
       }

       .hero,
       .form-card {
         background: var(--panel);
         border: 1px solid var(--panel-border);
         border-radius: var(--radius);
         box-shadow: var(--shadow);
         backdrop-filter: blur(18px);
       }

       .hero {
         padding: 2rem;
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 0.5rem;
         margin: 0 0 1rem;
         padding: 0.4rem 0.75rem;
         border: 1px solid rgba(125, 211, 252, 0.28);
         border-radius: 999px;
         color: var(--primary);
         background: rgba(14, 165, 233, 0.12);
         font-size: 0.875rem;
         font-weight: 700;
         letter-spacing: 0.01em;
       }

       h1 {
         margin: 0 0 0.75rem;
         font-size: clamp(2rem, 5vw, 3.4rem);
         line-height: 1.1;
       }

       .hero p,
       .form-intro {
         margin: 0;
         max-width: 62ch;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.7;
       }

       .form-card {
         padding: 1.5rem;
       }

       .form-card h2 {
         margin: 0 0 0.5rem;
         font-size: 1.375rem;
       }

       .required-note {
         margin: 0 0 1.5rem;
         color: var(--muted);
         font-size: 0.95rem;
       }

       form {
         display: grid;
         gap: 1rem;
       }

       .form-field {
         display: grid;
         gap: 0.45rem;
       }

       label {
         font-weight: 700;
       }

       .required-indicator {
         color: #f8fafc;
       }

       input {
         width: 100%;
         min-height: 3rem;
         padding: 0.85rem 0.95rem;
         border: 1px solid rgba(148, 163, 184, 0.28);
         border-radius: 0.9rem;
         background: rgba(15, 23, 42, 0.78);
         color: var(--text);
         transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
       }

       input::placeholder {
         color: #7c8ba1;
       }

       input:hover {
         border-color: rgba(125, 211, 252, 0.35);
       }

       input:focus-visible,
       button:focus-visible {
         outline: 3px solid transparent;
         box-shadow: 0 0 0 3px rgba(125, 211, 252, 0.9);
       }

       input[aria-invalid="true"] {
         border-color: var(--danger-strong);
         box-shadow: 0 0 0 1px rgba(239, 68, 68, 0.45);
       }

       .field-help,
       .error-message,
       .status-message {
         margin: 0;
         font-size: 0.93rem;
         line-height: 1.5;
       }

       .field-help {
         color: var(--muted);
       }

       .error-message {
         color: var(--danger);
       }

       .status-message {
         min-height: 1.5rem;
         color: var(--success);
       }

       .status-message[data-status="error"] {
         color: var(--danger);
       }

       .actions {
         display: flex;
         flex-wrap: wrap;
         align-items: center;
         gap: 1rem;
         margin-top: 0.5rem;
       }

       button {
         border: 0;
         border-radius: 999px;
         padding: 0.95rem 1.4rem;
         min-height: 3rem;
         background: linear-gradient(135deg, var(--primary) 0%, var(--primary-strong) 100%);
         color: #03121d;
         font-weight: 800;
         cursor: pointer;
       }

       button:hover {
         filter: brightness(1.08);
       }

       @media (min-width: 720px) {
         main {
           padding-top: 4.5rem;
         }

         .page-shell {
           grid-template-columns: minmax(0, 1.05fr) minmax(19rem, 0.95fr);
         }

         .hero,
         .form-card {
           padding: 2rem;
         }
       }

       @media (forced-colors: active) {
         .hero,
         .form-card,
         input,
         button,
         .skip-link {
           forced-color-adjust: auto;
           border: 1px solid CanvasText;
         }
       }
     </style>
   </head>
   <body>
     <div id="app"></div>
     <script>
       const fields = {
         fullName: {
           label: "Full name",
           type: "text",
           autocomplete: "name",
           required: true,
           inputMode: "text",
           errorId: "full-name-error",
           getError(value) {
             return value.trim() ? "" : "Error: Enter your full name.";
           }
         },
         email: {
           label: "Email address",
           type: "email",
           autocomplete: "email",
           required: true,
           inputMode: "email",
           errorId: "email-address-error",
           getError(value) {
             if (!value.trim()) {
               return "Error: Enter your email address.";
             }

             const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
             return emailPattern.test(value.trim())
               ? ""
               : "Error: Enter a valid email address, such as name@example.com.";
           }
         },
         phone: {
           label: "Phone number",
           type: "tel",
           autocomplete: "tel",
           required: false,
           inputMode: "tel",
           helpId: "phone-number-help",
           helpText: "Optional. Use digits, spaces, hyphens, or parentheses, for example +1 555 123 4567.",
           errorId: "phone-number-error",
           getError(value) {
             if (!value.trim()) {
               return "";
             }

             const phonePattern = /^[+]?[\d\s().-]{7,20}$/;
             return phonePattern.test(value.trim())
               ? ""
               : "Error: Enter a phone number in a format like +1 555 123 4567.";
           }
         }
       };

       function Field({ id, name, config }) {
         const requiredText = config.required
           ? ' <span class="required-indicator" aria-hidden="true">*</span>'
           : ' <span class="field-help">(optional)</span>';
         const help = config.helpText
           ? '<p class="field-help" id="' + config.helpId + '">' + config.helpText + "</p>"
           : "";

         return `
           <div class="form-field" data-field="${name}">
             <label for="${id}">${config.label}${requiredText}</label>
              <input
                id="${id}"
                name="${name}"
                type="${config.type}"
                ${config.required ? "required" : ""}
                autocomplete="${config.autocomplete}"
                inputmode="${config.inputMode}"
                ${config.helpId ? 'aria-describedby="' + config.helpId + '"' : ""}
              />
             ${help}
             <p class="error-message" id="${config.errorId}" hidden></p>
           </div>
         `;
       }

       function ContactForm() {
         return `
           <section class="form-card" aria-labelledby="support-form-heading">
             <h2 id="support-form-heading">Send a support request</h2>
             <p class="form-intro">Share your details and our team will get back to you with the next best step.</p>
             <p class="required-note"><span class="required-indicator" aria-hidden="true">*</span> Required fields</p>
             <form id="support-form" novalidate>
               ${Field({ id: "full-name", name: "fullName", config: fields.fullName })}
               ${Field({ id: "email-address", name: "email", config: fields.email })}
               ${Field({ id: "phone-number", name: "phone", config: fields.phone })}
               <div class="actions">
                 <button type="submit">Send support request</button>
                 <p class="status-message" id="form-status" aria-live="polite"></p>
               </div>
             </form>
           </section>
         `;
       }

       function Hero() {
         return `
           <section class="hero" aria-labelledby="page-title">
             <p class="eyebrow">Support</p>
             <h1 id="page-title">Let us help you faster.</h1>
             <p>Use this form to reach our support team with your contact details. Required fields are clearly marked, and your phone number is only needed if you want a call back.</p>
           </section>
         `;
       }

       function App() {
         return `
           <a class="skip-link" href="#main-content">Skip to main content</a>
           <main id="main-content">
             <div class="page-shell">
               ${Hero()}
               ${ContactForm()}
             </div>
           </main>
         `;
       }

       document.getElementById("app").innerHTML = App();

       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");
       let hasSubmitted = false;

       function updateFieldState(name) {
         const config = fields[name];
         const input = form.elements[name];
         const error = document.getElementById(config.errorId);
         const message = config.getError(input.value);
         const describedByIds = [];

         if (config.helpId) {
           describedByIds.push(config.helpId);
         }

         if (message) {
           input.setAttribute("aria-invalid", "true");
           input.setAttribute("aria-errormessage", config.errorId);
           error.textContent = message;
           error.hidden = false;
           describedByIds.push(config.errorId);
         } else {
           input.removeAttribute("aria-invalid");
           input.removeAttribute("aria-errormessage");
           error.textContent = "";
           error.hidden = true;
         }

         if (describedByIds.length > 0) {
           input.setAttribute("aria-describedby", describedByIds.join(" "));
         } else {
           input.removeAttribute("aria-describedby");
         }

         return message;
       }

       Object.keys(fields).forEach((name) => {
         form.elements[name].addEventListener("input", () => {
           status.textContent = "";
           delete status.dataset.status;

           if (hasSubmitted) {
             updateFieldState(name);
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         hasSubmitted = true;

         const invalidNames = Object.keys(fields).filter((name) => updateFieldState(name));

         if (invalidNames.length > 0) {
           status.dataset.status = "error";
           status.textContent = "Please correct the highlighted fields and try again.";
           form.elements[invalidNames[0]].focus();
           return;
         }

         status.dataset.status = "success";
         status.textContent = "Your support request is ready to send.";
       });
     </script>
   </body>
 </html>

